import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture as textureNode } from 'three/tsl';
import gsap from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  // Root object
  const root = new THREE.Object3D();

  // Apply placement
  if (config.position) root.position.set(config.position.x ?? 0, config.position.y ?? 0, config.position.z ?? 0);
  if (config.rotation) root.rotation.set(config.rotation.x ?? 0, config.rotation.y ?? 0, config.rotation.z ?? 0);
  if (config.scale) root.scale.set(config.scale.x ?? 1, config.scale.y ?? 1, config.scale.z ?? 1);

  // Load texture (ceramic grain map)
  const tex = ctx.textureLoader?.(config.assets?.imageUrl);
  if (tex) {
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
    tex.needsUpdate = true;
  }

  // Atlas region handling
  const rect = config.atlasRegion?.rect || { x: 0, y: 0, width: 512, height: 320 };
  const atlasWidth = tex?.image?.width ?? 1;
  const atlasHeight = tex?.image?.height ?? 1;

  const u0 = rect.x / atlasWidth;
  const v0 = rect.y / atlasHeight;
  const u1 = (rect.x + rect.width) / atlasWidth;
  const v1 = (rect.y + rect.height) / atlasHeight;

  // Plane geometry sized to aspect ratio of the atlas region
  const aspect = rect.width / rect.height;
  const geometry = new THREE.PlaneGeometry(aspect, 1);

  // Adjust UVs to sample only the atlas region
  const uvAttr = geometry.attributes.uv;
  const uvArray = uvAttr.array;
  // UV order for PlaneGeometry: (0,0), (1,0), (0,1), (1,1)
  uvArray[0] = u0; uvArray[1] = v1; // top‑left
  uvArray[2] = u1; uvArray[3] = v1; // top‑right
  uvArray[4] = u0; uvArray[5] = v0; // bottom‑left
  uvArray[6] = u1; uvArray[7] = v0; // bottom‑right
  uvAttr.needsUpdate = true;

  // Node‑based material
  const material = new MeshBasicNodeMaterial({
    map: textureNode(tex)
  });

  const mesh = new THREE.Mesh(geometry, material);
  // Billboard‑style orientation toward camera
  mesh.onBeforeRender = (renderer, scene, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };
  root.add(mesh);

  // Apply any cinematic primitives declared in the config
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[prim.name];
      if (typeof fn === 'function') {
        fn(root, prim.params);
      }
    }
  }

  // Event handlers placeholder (no DOM listeners)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (tex?.dispose) tex.dispose();
    // Kill any GSAP timelines that might have been created elsewhere
    gsap.globalTimeline.clear();
  };

  return root;
}
